private fun icon(pathData: String, autoMirror: Boolean = false): ImageVector =
    ImageVector.Builder(
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
        autoMirror = autoMirror,
    ).apply {
        // Black fill matching the Material source; Icon() tints over it, exactly as it did for the
        // androidx icons these replace.
        addPath(PathParser().parsePathString(pathData).toNodes(), fill = SolidColor(Color.Black))
    }.build()
